import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.CyZTVJbV.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.10/x-thread-ja.md","filePath":"announcements/v1.10/x-thread-ja.md"}'),o={name:"announcements/v1.10/x-thread-ja.md"};function i(c,e,p,n,d,l){return t(),s("div",null,[...e[0]||(e[0]=[r('<p>1/ 🌱 kiwa v1.10 リリース — SaaS + self-host + polyglot の 3 軸並行拡張。</p><p>v1.9 で auth / queue / cache の provider gap を埋めた後、 v1.10 は 3 つの新次元を開拓。</p><p>Supabase Auth (core + advanced)、 RabbitMQ (basic + advanced)、 Rust contract layer (Foundry-rs + alloy.rs)。</p><p>6/6 sub-issues 全 resolved。</p><p>2/ <code>@kiwa-test/auth</code> v0.3 — Supabase Auth (2 adapter)。</p><p>Core: PKCE OAuth、 magic link、 SMS OTP、 JWT HS256 + refresh rotation。</p><p>Advanced: RLS policy シミュレーション (SELECT/INSERT/UPDATE/DELETE + service_role bypass)、 MFA (TOTP RFC 6238 + backup codes + SMS AAL upgrade)、 SSO SAML 2.0 (SP-initiated + tampering 検知)、 Web3 SIWE (EIP-4361 + replay 保護)。</p><p>3/ <code>@kiwa-test/queue</code> v0.3 — RabbitMQ (2 adapter)。</p><p>Basic: 4 exchange type (direct / topic / fanout / headers、 wildcards + x-match)、 consumer + ack/nack、 prefetch QoS、 mandatory return。</p><p>Advanced: DLX + maxDeliveries、 delayed message plugin (<code>x-delayed-message</code> + deterministic advanceClock)、 3-node cluster + quorum queue + assertQuorumHealthy、 federation upstream/link、 amqp-connection-manager exponential backoff。</p><p>4/ <code>kiwa-test-rs</code> v0.4.2 — Rust contract layer。</p><p>Foundry adapter: <code>FoundryEnv::detect</code> graceful skip、 <code>Anvil::spawn_deterministic</code> + Drop cleanup + wait_ready TCP probe、 <code>forge test</code> + coverage (summary + lcov)、 <code>cast call/send/rpc</code> wrapper。</p><p>alloy adapter: <code>SolAbi</code> JSON parser、 built-in keccak-256 selector、 Signer enum (LocalWallet / AwsKms / Ledger / Trezor)、 Provider enum (Http / Ws / Ipc)、 <code>ContractCall</code> encoding。</p><p>heavy dep 追加なし — alloy crate family も pull しない。</p><p>5/ Layer 1 spec + skill chain 拡張。</p><p><code>/kiwa-design --layer contract-rust --provider {foundry|alloy}</code> で Rust contract test 用 9 column 拡張表を生成 (対象 contract / method / 呼出方向 / signer / provider / assertion 型)。</p><p>Layer 2 <code>/kiwa-rust --layer contract-rust --provider ...</code> が spec を read して Rust test file 生成。</p><p>6/ v1.9 user は zero-migration。</p><p>既存 test file はそのまま動く。 v1.10 追加は全て opt-in (Rust は feature gate、 TS は新関数呼出)。</p><p>Rust update:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kiwa-test-rs = { version = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.4.2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, features = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;contract-foundry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;contract-alloy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>7/ v1.10 milestone: <a href="https://github.com/cardene777/kiwa/issues/666" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/issues/666</a></p><p>次 v1.11 候補は Storybook integration、 Dragonfly (2025 新興 cache)、 Reth (Rust Ethereum 実行 client)、 Go Iris + Chi (framework 縦深化) 等。</p><p>kiwa の release cadence 追いたい人は @cardene777 まで。</p>',24)])])}const k=a(o,[["render",i]]);export{h as __pageData,k as default};
